int bits_read = 0;

while (bits_read < encoded_length) {
    // Read a byte from the file
    unsigned char byte;
    infile.read(reinterpret_cast<char*>(&byte), 1);
    if (!infile) break;

    // Extract each bit from the byte (from MSB to LSB)
    for (int i = 7; i >= 0; i--) {
        if (bits_read >= encoded_length) break;

        // Check the i-th bit (from left to right)
        if (byte & (1 << i)) {
            current = current->right;
        } else {
            current = current->left;
        }

        bits_read++;

        // If we reached a leaf node (both children are null)
        if (current->left == nullptr && current->right == nullptr) {
            decoded_text += current->character;
            current = root; // Reset to root for next character
        }
    }
}

return decoded_text;

